#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_HEAP 15

static long heap[MAX_HEAP];
static int size = 0;

static void heap_swap(int i, int j) {
    long tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

static void heapify_up(int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap[parent] <= heap[idx])
            break;
        heap_swap(parent, idx);
        idx = parent;
    }
}

static void heapify_down(int idx) {
    while (1) {
        int left = idx * 2 + 1;
        int right = left + 1;
        int smallest = idx;
        if (left < size && heap[left] < heap[smallest])
            smallest = left;
        if (right < size && heap[right] < heap[smallest])
            smallest = right;
        if (smallest == idx)
            break;
        heap_swap(idx, smallest);
        idx = smallest;
    }
}

static void insert_value(long val) {
    if (size >= MAX_HEAP) {
        puts("FULL");
        return;
    }
    heap[size] = val;
    heapify_up(size);
    size++;
    printf("INS %ld\n", val);
}

static void extract_min(void) {
    if (size == 0) {
        puts("EMPTY");
        return;
    }
    long min = heap[0];
    heap[0] = heap[size - 1];
    size--;
    heapify_down(0);
    printf("MIN %ld\n", min);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (arg[0] == 'I') {
            char *endptr;
            long val = strtol(arg + 1, &endptr, 10);
            if (*endptr != '\0') {
                puts("ERR");
                continue;
            }
            insert_value(val);
        } else if (strcmp(arg, "X") == 0) {
            extract_min();
        } else {
            puts("ERR");
        }
    }
    return 0;
}
